{"content":"import json


class Inventory:
    def __init__(self):
        self._items = {}  # sku -> {"qty": int, "price": float}

    def add(self, sku, qty, price):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if price < 0:
            raise ValueError("price must be non-negative")
        if sku in self._items:
            self._items[sku]["qty"] += qty
            self._items[sku]["price"] = price
        else:
            self._items[sku] = {"qty": qty, "price": price}

    def remove(self, sku, qty):
        if qty <= 0:
            raise ValueError("qty must be positive")
        item = self._items.get(sku)
        if item is None or item["qty"] < qty:
            raise ValueError("not enough stock")
        item["qty"] -= qty
        if item["qty"] == 0:
            del self._items[sku]

    def total_value(self):
        return sum(item["qty"] * item["price"] for item in self._items.values())

    def low_stock(self, threshold):
        return sorted(
            (sku for sku, item in self._items.items() if item["qty"] <= threshold),
            key=lambda sku: (self._items[sku]["qty"], sku),
        )

    def to_json(self):
        return json.dumps({sku: dict(item) for sku, item in self._items.items()})

    @classmethod
    def from_json(cls, data):
        inv = cls()
        for sku, item in json.loads(data).items():
            inv._items[sku] = {"qty": item["qty"], "price": item["price"]}
        return inv
